export function writeSequenceAnimationTransforms(channels,state,plan,options,vm,hooks){
 if(!plan)return;const {object,sample,imported}=plan,program=sample.program;if(imported){const rows=imported.rows.map(row=>{const target=row.node===hooks.mesh(object.id)?object:row.node,basis=channels.preanimated(target,row.field)??options(target,row.field).read(),value=imported.sample(row,sample.time,row.indexed&&target===object?state.origin.indexedBasis(row.field,basis,object):basis),partial=row.indexed&&row.field!=='rotation',sampled=partial?{indexedTransform:true,value,mask:row.mask}:value;return {target,key:row.field,value:target===object?partial?state.origin.applyPartial(row.field,sampled,basis,object):state.origin.apply({type:row.field},value,object):sampled,resolve:partial?resolveIndexedTransformEntries:undefined,options:()=>options(target,row.field),completionMode:sample.track.completionMode};});return channels.writeBatch(state,rows);}const time=Math.max(0,Math.min(program.length??timelineLength(program.timeline),sample.time));
 for(const track of program.tracks){const value=state.origin.apply({type:track.id},sampleTimeline(track,time),object);channels.write(state,object,track.id,value,()=>options(object,track.id),sample.track.completionMode);}
}
export function reapplySequenceTransforms(channels,object){let changed=false;for(const field of fields){const value=channels.presentation(object,field);if(value!==undefined&&(!Array.isArray(object[field])||object[field].length!==value.length||value.some((n,i)=>object[field][i]!==n))){object[field]=value.slice();changed=true;}}return changed;}
export const sequenceAnimationTransformContract={fields:'HB and imported actor-root transform clips project position/rotation/scale into the same actor-identity field leases as direct TRS and Transform component tracks; imported model children use actual-node local field leases. Existing last active animation track per actor remains; authored order resolves direct-versus-clip writes within one sequence.',arbitration:'Across sequences, shared priority/start order, normalized weights, quaternion rotation, zero yield and completion policies operate per field; disjoint fields remain independent. Hidden samples update without publishing.',baseline:'Capture new field baselines before old animation suspension or any current-frame transform writes. Restore canonical fields before animation evaluator presentation; replay active canonical values after a resumed or ordinary external HB timeline so it cannot overwrite a stronger track.',origin:'Apply the owning sequence origin to HB clip root position/rotation exactly as direct tracks; attached actors stay local. Actor-origin clip targets are ordered before dependents; animated origin parents are rejected by the existing cycle rule.',lifetime:'Only active clip/field descriptors and first-lease vec3 baselines; no authored asset mutation, hidden source curves, scene snapshot, timer, worker or public API. Async asset preparation checks the same current sequence before writes. Clip gaps release only expired fields.',remaining:['independent Euler-axis layer composition','renderer/component aliases beyond canonical Transform','arbitrary external simulation/notify/async setter rollback']};
